    col.xyz = mix( back.xyz, col.xyz, back.a );
    col.xyz = col.xyz*col.xyz*(1.0+contrast*(1.0-col.xyz));
    out_FragColor.rgb = mix(out_FragColor.rgb, col.xyz, col.a );
